const Home = () => {
  const [activeCategory, setActiveCategory] = useState('All');
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('latest');
  const [favorites, setFavorites] = useState(new Set());
  const [loading, setLoading] = useState(false);
  const [failedImages, setFailedImages] = useState(new Set());

  // Handle image load error - add to failed set to use fallback
  const handleImageError = (productId) => {
    setFailedImages((prev) => new Set([...prev, productId]));
  };

  // Get image URL with fallback
  const getImageUrl = (product) => {
    if (failedImages.has(product.id) || !product.image) {
      return FALLBACK_IMAGE;
    }
    return product.image;
  };

  const filteredProducts = useMemo(() => {
    let result = products.filter((product) => {
      const matchesCategory = activeCategory === 'All' || product.category === activeCategory;
      const matchesSearch = product.title.toLowerCase().includes(search.toLowerCase());
      return matchesCategory && matchesSearch;
    });

    // Sort products
    if (sortBy === 'price-low') {
      result.sort((a, b) => parseInt(a.price) - parseInt(b.price));
    } else if (sortBy === 'price-high') {
      result.sort((a, b) => parseInt(b.price) - parseInt(a.price));
    }

    return result;
  }, [activeCategory, search, sortBy]);

  const toggleFavorite = (productId) => {
    setFavorites((prev) => {
      const newFavorites = new Set(prev);
      if (newFavorites.has(productId)) {
        newFavorites.delete(productId);
      } else {
        newFavorites.add(productId);
      }
      return newFavorites;
    });
  };

  // Simulate loading
  useEffect(() => {
    setLoading(true);
    const timer = setTimeout(() => setLoading(false), 800);
    return () => clearTimeout(timer);
  }, [activeCategory, search]);

  return (
    <main className="page-shell home-page">
      <section className="hero-panel" style={{
  background: 'linear-gradient(135deg, #e0fdf4 0%, #ccfbf1 50%, #a7f3d0 100%)',
  padding: '60px 40px',
  textAlign: 'center'
}}>
  {/* Trust badge */}
  <div style={{
    display: 'inline-flex', alignItems: 'center', gap: '8px',
    background: 'rgba(255,255,255,0.7)', border: '1px solid #6ee7b7',
    borderRadius: '999px', padding: '6px 16px',
    fontSize: '13px', fontWeight: '600', color: '#065f46',
    marginBottom: '24px'
  }}>
    🎓 Trusted by 10,000+ Students
  </div>

  <h1 style={{
    fontSize: 'clamp(32px, 5vw, 56px)', fontWeight: '800',
    color: '#065f46', marginBottom: '16px', lineHeight: '1.2'
  }}>
    Your Campus, Your Marketplace
  </h1>

  <p style={{
    fontSize: '18px', color: '#047857', marginBottom: '36px', fontWeight: '400'
  }}>
    Buy and sell textbooks, tech, furniture & more from students nearby
  </p>

  {/* Search bar */}
  <div style={{
    background: 'white', borderRadius: '999px',
    padding: '14px 24px', display: 'flex', alignItems: 'center',
    gap: '12px', maxWidth: '680px', margin: '0 auto 40px',
    boxShadow: '0 4px 20px rgba(0,0,0,0.08)'
  }}>
    <span style={{ fontSize: '18px', color: '#6b7280' }}>🔍</span>
    <input
      type="search"
      value={search}
      onChange={(e) => setSearch(e.target.value)}
      placeholder="Search for anything... textbooks, laptops, furniture"
      style={{
        flex: 1, border: 'none', outline: 'none',
        fontSize: '15px', color: '#374151', background: 'transparent'
      }}
    />
  </div>

  {/* Category chips */}
  <div style={{
    display: 'flex', flexWrap: 'wrap', justifyContent: 'center',
    gap: '10px', maxWidth: '800px', margin: '0 auto'
  }}>
    {categories.slice(0, 7).map((cat) => (
      <button
        key={cat.name}
        onClick={() => setActiveCategory(cat.name)}
        style={{
          display: 'flex', alignItems: 'center', gap: '8px',
          padding: '12px 20px', borderRadius: '14px', cursor: 'pointer',
          fontWeight: '600', fontSize: '14px', border: '1px solid',
          transition: 'all 0.2s',
          background: activeCategory === cat.name ? '#059669' : 'white',
          color: activeCategory === cat.name ? 'white' : '#374151',
          borderColor: activeCategory === cat.name ? '#059669' : '#e5e7eb',
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)'
        }}
      >
        <span>{cat.icon}</span>
        <span>{cat.name}</span>
      </button>
    ))}
  </div>
</section>

      <section className="categories-section">
        <div className="categories-scroll-container">
          <div className="categories-row">
            {categories.map((cat) => (
              <button
                key={cat.name}
                className={`category-chip ${activeCategory === cat.name ? 'active' : ''}`}
                onClick={() => setActiveCategory(cat.name)}
                type="button"
                title={cat.name}
              >
                <span className="category-icon">{cat.icon}</span>
                <span className="category-label">{cat.name}</span>
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Marketplace Toolbar */}
      <section className="marketplace-toolbar">
        <div className="toolbar-left">
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="sort-dropdown"
            aria-label="Sort products"
          >
            <option value="latest">Latest</option>
            <option value="price-low">Price: Low to High</option>
            <option value="price-high">Price: High to Low</option>
          </select>

          <button
            type="button"
            className={`favorites-toggle ${favorites.size > 0 ? 'active' : ''}`}
            title={`${favorites.size} favorite${favorites.size !== 1 ? 's' : ''}`}
          >
            <span className="heart-icon">❤️</span>
            <span>{favorites.size > 0 ? favorites.size : 'Favorites'}</span>
          </button>
        </div>

        <div className="results-count">
          <span style={{ color: '#cbd5f5', fontWeight: '600' }}>
            {filteredProducts.length} result{filteredProducts.length !== 1 ? 's' : ''}
          </span>
        </div>
      </section>

      {/* Loading Skeleton */}
      {loading && (
        <section className="products-grid">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="skeleton-card">
              <div className="skeleton-image skeleton"></div>
              <div className="skeleton-body">
                <div className="skeleton-title skeleton"></div>
                <div className="skeleton-price skeleton"></div>
                <div className="skeleton-category skeleton"></div>
              </div>
            </div>
          ))}
        </section>
      )}

      {/* Products Grid or Empty State */}
      {!loading && filteredProducts.length > 0 ? (
        <section className="products-grid">
          {filteredProducts.map((product) => (
            <article key={product.id} className="product-card">
              <div className="card-image">
                <img
                  src={getImageUrl(product)}
                  alt={product.title}
                  className="product-image"
                  onError={() => handleImageError(product.id)}
                  loading="lazy"
                />
                <span className="badge">{product.badge}</span>
                <button
                  className="bookmark-icon"
                  type="button"
                  onClick={() => toggleFavorite(product.id)}
                  style={{
                    background: favorites.has(product.id)
                      ? 'linear-gradient(135deg, #ec4899, #f43f5e)'
                      : 'rgba(15, 23, 42, 0.85)',
                    transform: favorites.has(product.id) ? 'scale(1.1)' : 'scale(1)',
                    transition: 'all 0.2s ease'
                  }}
                  title={favorites.has(product.id) ? 'Remove from favorites' : 'Add to favorites'}
                >
                  {favorites.has(product.id) ? '❤️' : '🤍'}
                </button>
              </div>
              <div className="card-body">
                <h3>{product.title}</h3>
                <p className="card-price">${product.price}</p>
                <div className="card-meta">
                  <span className="card-category">{product.category}</span>
                  <Link to={`/product/${product.id}`} className="card-link">
                    View
                  </Link>
                </div>
              </div>
            </article>
          ))}
        </section>
      ) : !loading ? (
        <section className="empty-state">
          <div className="empty-state-icon">📦</div>
          <h2 className="empty-state-title">No products found</h2>
          <p className="empty-state-description">
            {search
              ? `No results for "${search}". Try adjusting your search or browse all products.`
              : activeCategory !== 'All'
              ? `No products in the ${activeCategory} category. Try another category or post a new item!`
              : 'No products available right now. Be the first to post one!'}
          </p>
          {search || activeCategory !== 'All' ? (
            <>
              <button
                type="button"
                className="empty-state-action"
                onClick={() => {
                  setSearch('');
                  setActiveCategory('All');
                }}
              >
                ← Clear filters
              </button>
            </>
          ) : (
            <Link to="/sell" className="empty-state-action">
              ➕ Post first item
            </Link>
          )}
        </section>
      ) : null}
    </main>
  );
};

export default Home;
